//! Typed parsing with a schema generated by `schemars`.

use std::fmt;

use schemars::JsonSchema;
use serde::de::DeserializeOwned;

use crate::{Fix, Fixer, Outcome, SchemaError};

/// Why [`parse`] could not produce a `T`.
#[derive(Debug)]
pub enum FixError {
    /// The generated schema could not be compiled.
    Schema(SchemaError),
    /// The output still violates the schema; call `retry_hint()` on it.
    Invalid(Outcome),
    /// The corrected value validated but did not deserialize into `T`.
    Deserialize(serde_json::Error),
}

impl fmt::Display for FixError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Schema(err) => err.fmt(f),
            Self::Invalid(outcome) => {
                let hint = outcome.retry_hint().unwrap_or_default();
                write!(f, "output does not match schema: {hint}")
            }
            Self::Deserialize(err) => write!(f, "deserialize failed: {err}"),
        }
    }
}

impl std::error::Error for FixError {}

/// Repair, correct and validate `raw` against `T`'s schema, then deserialize.
pub fn parse<T: DeserializeOwned + JsonSchema>(raw: &str) -> Result<(T, Vec<Fix>), FixError> {
    let schema = schemars::schema_for!(T).to_value();
    let fixer = Fixer::new(&schema).map_err(FixError::Schema)?;
    let (value, fixes) = match fixer.fix(raw) {
        Outcome::Valid { value } => (value, Vec::new()),
        Outcome::Fixed { value, fixes } => (value, fixes),
        invalid @ Outcome::Invalid { .. } => return Err(FixError::Invalid(invalid)),
    };
    let typed = serde_json::from_value(value).map_err(FixError::Deserialize)?;
    Ok((typed, fixes))
}
